<script lang="ts">
 import {catalogApi} from '$lib/api/catalog';import type {CharacterForm} from '$lib/types';import {normalizeBuild,type CharacterOption} from '$lib/rules/characterBuilder';import {creationTasks} from '$lib/rules/creationChoices';
 export let form:CharacterForm;export let readonly=false;let options:CharacterOption[]=[];let current='';let loading=false;let error='';
 $: build=normalizeBuild(form.build);$: keys=[build.class,build.subclass,build.species,build.variant,build.background,...build.feats].map(v=>v.key).filter(Boolean).join('|');
 $: if(keys!==current){current=keys;load(keys);}
 async function load(signature:string){loading=true;error='';try{const rows=await Promise.all(signature.split('|').filter(Boolean).map(key=>catalogApi.getOption(key)));if(signature===current)options=rows;}catch{if(signature===current)error='No se pudieron consultar todas las elecciones del catálogo. Reintentá.';}finally{if(signature===current)loading=false;}}
 $: tasks=creationTasks(form,options);$: pending=tasks.filter(t=>!t.done).length;
 function toggle(id:string){if(readonly||!form.build)return;const checks=form.build.choiceChecks||[];form.build.choiceChecks=checks.includes(id)?checks.filter(key=>key!==id):[...checks,id].slice(0,200);}
</script>
<details class="border border-primary/30 rounded p-3 text-neutral"><summary class="cursor-pointer font-medieval font-semibold">Revisión de personaje · {pending} pendiente(s)</summary><p class="text-xs my-2">Guía de creación y subida de nivel. Las confirmaciones manuales indican que revisaste la elección; no prueban que todas las combinaciones sean legales. Podés guardar una ficha en preparación.</p>{#if loading}<p class="text-xs">Consultando rasgos del nivel…</p>{/if}{#if error}<p class="text-error text-sm">{error} <button class="link" type="button" on:click={()=>load(current)}>Reintentar</button></p>{/if}{#each tasks as task}<div class="border-t border-primary/20 py-2"><label class="flex items-start gap-2"><input class="checkbox checkbox-sm border-neutral/70 text-primary bg-white/30 shrink-0 mt-1" type="checkbox" checked={task.done} disabled={readonly||!task.manual} on:change={()=>toggle(task.id)}/><span class="text-sm"><strong>{task.label}</strong><span class="block text-xs opacity-75">{task.detail}</span></span></label></div>{/each}</details>
